class TaskForm {
  @on('keydown')
  handleKey(event: KeyboardEvent) {
    if (event.key === 'Enter') this.addTask();
  }
}

import { html } from 'snice';
class TaskForm {
  render() {
    return html`<input @keydown=${this.handleKey} />`;
  }
  handleKey(event: KeyboardEvent) {
    if (event.key === 'Escape') this.clear();
  }
}

class Editor {
  @on('keydown:Enter')
  handleEnter(event: KeyboardEvent) {
    this.save();
  }
  @on('keydown:Ctrl+S')
  handleSave(event: KeyboardEvent) {
    event.preventDefault();
    this.save();
  }
}

import { html } from 'snice';
class TaskForm {
  render() {
    return html`<input @keydown:Enter|prevent=${this.addTask} @keydown:Escape|stop=${this.clear} @keydown.ctrl+s=${this.save} />`;
  }
}
